using System.ComponentModel.DataAnnotations;

namespace INKED.Application.Products;

/// <summary>Data the client sends to update a product. ProductID is generated by SQL Server.</summary>
public class UpdateProductDto
{
    /// <summary>Must be an existing CategoryID in ProductCategories.</summary>
    [Range(1, int.MaxValue, ErrorMessage = "CategoryId must be an existing category ID.")]
    public int CategoryId { get; set; }

    /// <summary>VARCHAR(100), required, unique, not blank.</summary>
    [Required, StringLength(100, MinimumLength = 1)]
    public string ProductName { get; set; } = string.Empty;

    /// <summary>VARCHAR(300), optional.</summary>
    [StringLength(300)]
    public string? Description { get; set; }

    /// <summary>DECIMAL(10,2), must be 0 or more.</summary>
    [Range(typeof(decimal), "0", "99999999.99", ErrorMessage = "BasePrice must be from 0 to 99,999,999.99.")]
    public decimal BasePrice { get; set; }

    /// <summary>Set false to retire the product without deleting it.</summary>
    public bool IsActive { get; set; } = true;
}
